def linked_read(head, index):
    if index < 0:
        return None
    node = head
    position = 0
    while node is not None:
        if position == index:
            return node.value
        node = node.next
        position += 1
    return None

print(linked_read(make_chain([8, 3, 8]), 2))
print(linked_read(make_chain([8]), 1))
print(linked_read(None, 0))

