def delete_after(node):
    if node is None or node.next is None:
        return None
    removed = node.next
    node.next = removed.next
    return removed.value

head = make_chain([1, 2, 3])
print(delete_after(head), chain_values(head))
head = make_chain([4])
print(delete_after(head), chain_values(head))
print(delete_after(None))
